interface LogoMarqueeProps {
  className?: string;
}

export function LogoMarquee({ className }: LogoMarqueeProps) {
  // Duplicate list to create seamless infinite loop
  const duplicatedMarks = [...BRAND_MARKS, ...BRAND_MARKS];

  return (
    <div
      className={cn(
        'relative w-full overflow-hidden py-2 select-none',
        '[mask-image:linear-gradient(to_right,transparent_0%,black_10%,black_90%,transparent_100%)]',
        className
      )}
    >
      {/* Left & Right gradient edge blurs */}
      <div className="pointer-events-none absolute inset-y-0 left-0 w-12 sm:w-20 bg-gradient-to-r from-card/80 to-transparent z-10" />
      <div className="pointer-events-none absolute inset-y-0 right-0 w-12 sm:w-20 bg-gradient-to-l from-card/80 to-transparent z-10" />

      <div className="flex gap-14 sm:gap-20 w-max animate-[marquee_32s_linear_infinite]">
        {duplicatedMarks.map((brand, idx) => (
          <a
            key={`${brand.name}-${idx}`}
            href={brand.url}
            target="_blank"
            rel="noopener noreferrer"
            className="flex items-center gap-2.5 text-muted-foreground/75 hover:text-foreground hover:opacity-100 transition-all cursor-pointer group"
            title={`${brand.name} (${brand.domain})`}
          >
            <div className="shrink-0 group-hover:scale-105 transition-transform">
              {brand.render()}
            </div>
            <div className="flex items-baseline gap-1.5">
              <span className="font-bold tracking-tight text-base sm:text-[18px]">
                {brand.name}
              </span>
              <span className="text-xs text-muted font-mono tracking-tight opacity-70 group-hover:opacity-100 transition-opacity">
                {brand.domain}
              </span>
            </div>
          </a>
        ))}
      </div>
    </div>
  );
}
